begin;
select plan(31);
insert into public.properties(id,name,is_active) values('c1000000-0000-4000-8000-000000000001','Synthetic Inventory',true),('c1000000-0000-4000-8000-000000000002','Other Inventory',true);
insert into auth.users(id) values('c2000000-0000-4000-8000-000000000001'),('c2000000-0000-4000-8000-000000000002'),('c2000000-0000-4000-8000-000000000003');
insert into public.staff_access_profiles(user_id,role) values('c2000000-0000-4000-8000-000000000001','admin'),('c2000000-0000-4000-8000-000000000002','cleaner'),('c2000000-0000-4000-8000-000000000003','finance');
insert into public.staff_property_access(user_id,property_id) select id,'c1000000-0000-4000-8000-000000000001'::uuid from auth.users where id in ('c2000000-0000-4000-8000-000000000001','c2000000-0000-4000-8000-000000000002','c2000000-0000-4000-8000-000000000003');
insert into public.inventory_items(id,property_id,name,category,qty_on_hand) values('c3000000-0000-4000-8000-000000000001','c1000000-0000-4000-8000-000000000001','Synthetic soap','Supplies',20),('c3000000-0000-4000-8000-000000000002','c1000000-0000-4000-8000-000000000002','Other soap','Supplies',20);
select ok(not has_function_privilege('service_role','public.review_inventory_purchase(uuid,text,numeric,text,text)','execute'),'service cannot approve');
select ok(not has_table_privilege('authenticated','public.inventory_purchase_reviews','insert'),'cannot forge review');
select ok(not has_table_privilege('anon','public.inventory_forecasts','select'),'anonymous denied');
set local role authenticated;
set local request.jwt.claims='{"sub":"c2000000-0000-4000-8000-000000000001","aal":"aal1"}';
select throws_ok($$select public.forecast_inventory('c3000000-0000-4000-8000-000000000001',7,14,'wave4-forecast-key-01')$$,'42501',null,'AAL1 denied');
set local request.jwt.claims='{"sub":"c2000000-0000-4000-8000-000000000001","aal":"aal2"}';
select throws_ok($$select public.forecast_inventory('c3000000-0000-4000-8000-000000000002',7,14,'wave4-forecast-key-01')$$,'42501',null,'cross property denied');
select throws_ok($$select public.forecast_inventory('c3000000-0000-4000-8000-000000000001',7,14,'wave4-forecast-key-01')$$,'22023','stock reconciliation required','opening reconciliation required');
select lives_ok($$select public.record_inventory_movement('c3000000-0000-4000-8000-000000000001','reconcile',20,'Count verified','wave4-opening-key-01')$$,'named opening count');
select lives_ok($$select public.record_inventory_movement('c3000000-0000-4000-8000-000000000001','usage',-14,'Recorded consumption','wave4-usage-key-0001')$$,'usage reduces canonical stock');
select lives_ok($$select public.record_inventory_movement('c3000000-0000-4000-8000-000000000001','usage',-14,'Recorded consumption','wave4-usage-key-0001')$$,'exact retry');
select is((select qty_on_hand from public.inventory_items where id='c3000000-0000-4000-8000-000000000001'),6::numeric,'retry does not deduct twice');
select throws_ok($$select public.record_inventory_movement('c3000000-0000-4000-8000-000000000001','usage',-13,'Recorded consumption','wave4-usage-key-0001')$$,'22023','idempotency conflict','changed payload denied');
select throws_ok($$select public.record_inventory_movement('c3000000-0000-4000-8000-000000000001','receipt',0.001,'Invalid precision','wave4-precision-key1')$$,'22023',null,'subunit rounding denied');
select throws_ok($$select public.record_inventory_movement('c3000000-0000-4000-8000-000000000001','usage',-7,'Overdraw stock','wave4-overdraw-key01')$$,'23514',null,'negative stock denied');
select set_config('cascade.w4_forecast',public.forecast_inventory('c3000000-0000-4000-8000-000000000001',7,14,'wave4-forecast-key-01')::text,true);
select is((select recommended_quantity from public.inventory_forecasts where id=current_setting('cascade.w4_forecast')::uuid),22::numeric,'14 over 7 days times 14 minus 6 is 22');
select is(public.forecast_inventory('c3000000-0000-4000-8000-000000000001',7,14,'wave4-forecast-key-01'),current_setting('cascade.w4_forecast')::uuid,'forecast retry stable');
set local request.jwt.claims='{"sub":"c2000000-0000-4000-8000-000000000002","aal":"aal2"}';
select is((select count(*) from public.inventory_forecasts),0::bigint,'OPS cannot browse forecast approval data');
select throws_ok($$select public.review_inventory_purchase(current_setting('cascade.w4_forecast')::uuid,'approved',22,'Purchase needed','wave4-review-key-001')$$,'42501',null,'cleaner cannot approve');
set local request.jwt.claims='{"sub":"c2000000-0000-4000-8000-000000000003","aal":"aal2"}';
select throws_ok($$select public.review_inventory_purchase(current_setting('cascade.w4_forecast')::uuid,'approved',22,'Purchase needed','wave4-review-key-001')$$,'42501',null,'Finance alone cannot approve purchase');
set local request.jwt.claims='{"sub":"c2000000-0000-4000-8000-000000000001","aal":"aal2"}';
select set_config('cascade.w4_review',public.review_inventory_purchase(current_setting('cascade.w4_forecast')::uuid,'approved',22,'Purchase needed','wave4-review-key-001')::text,true);
select is(public.review_inventory_purchase(current_setting('cascade.w4_forecast')::uuid,'approved',22,'Purchase needed','wave4-review-key-001'),current_setting('cascade.w4_review')::uuid,'review exact retry');
select is((select reviewer_user_id from public.inventory_purchase_reviews where id=current_setting('cascade.w4_review')::uuid),'c2000000-0000-4000-8000-000000000001'::uuid,'named reviewer captured');
select is((select order_authorized from public.inventory_purchase_reviews where id=current_setting('cascade.w4_review')::uuid),false,'approval authorizes no provider action');
select throws_ok($$select public.review_inventory_purchase(current_setting('cascade.w4_forecast')::uuid,'approved',23,'Purchase needed','wave4-review-key-001')$$,'22023','review conflict','approved quantity immutable');
select set_config('cascade.w4_stale',public.forecast_inventory('c3000000-0000-4000-8000-000000000001',7,14,'wave4-forecast-key-02')::text,true);
select lives_ok($$select public.record_inventory_movement('c3000000-0000-4000-8000-000000000001','receipt',2,'Physical receipt','wave4-receipt-key-01')$$,'physical receipt independent of shopping approval');
select throws_ok($$select public.review_inventory_purchase(current_setting('cascade.w4_stale')::uuid,'approved',22,'Stale purchase','wave4-review-key-002')$$,'22023','stale forecast','changed stock blocks approval');
reset role;
update public.inventory_items set qty_on_hand=9 where id='c3000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.forecast_inventory('c3000000-0000-4000-8000-000000000001',7,14,'wave4-forecast-key-03')$$,'22023','stock reconciliation required','legacy drift blocks forecast');
select lives_ok($$select public.record_inventory_movement('c3000000-0000-4000-8000-000000000001','reconcile',9,'Legacy count checked','wave4-reconcile-key2')$$,'explicit reconciliation repairs drift');
select lives_ok($$select public.forecast_inventory('c3000000-0000-4000-8000-000000000001',7,14,'wave4-forecast-key-03')$$,'reconciled forecast works');
reset role;
update public.staff_access_profiles set disabled_at=now() where user_id='c2000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.forecast_inventory('c3000000-0000-4000-8000-000000000001',7,14,'wave4-forecast-key-04')$$,'42501',null,'disabled administrator denied');
reset role;
select is((select count(*) from public.inventory_purchase_reviews),1::bigint,'only one decision recorded');
select ok(not has_table_privilege('authenticated','public.inventory_purchase_reviews','update'),'review mutation forbidden');
select ok(not has_table_privilege('service_role','public.inventory_stock_movements','insert'),'integration cannot fabricate movements');
select * from finish();
rollback;
